const currentParty=r=>r.current?.party||'V';
function probability(r){if(r.notUp||!shift)return r.qD;const p=Math.max(.005,Math.min(.995,r.qD));return 1/(1+Math.exp(-(Math.log(p/(1-p))+shift/3.1)));}
function predictedParty(r){return r.notUp?r.party:((r.margin+shift)>=0?(r.nonRParty||'D'):(r.nonDParty||'R'));}
function winner(r){const p=predictedParty(r);if(!shift||p===r.party)return r.winner;return r.candidates.find(n=>DATA.people[n]?.party===p)||`${p==='D'?'Democratic':'Republican'} opponent`;}
function fillColor(r){if(!r)return '#26344a';if(showCurrent){return {D:'#3b71cd',R:'#b23e57',I:'#9d7dc8',V:'#75819a'}[currentParty(r)]||'#4b5e78';}if(r.notUp)return '#334259';if(predictedParty(r)==='I')return '#9275b9';const p=probability(r),isD=predictedParty(r)==='D',win=isD?p:1-p;return isD?(win>=.95?'#2455b6':win>=.8?'#3c7ae1':win>=.65?'#6ba2ee':'#9ec0f2'):(win>=.95?'#a82743':win>=.8?'#cb425c':win>=.65?'#d76979':'#b98d97');}
function raceForState(st){return DATA[office].find(r=>r.state===st);}
function totalFor(which){let d=which==='senate'?34:0,r=which==='senate'?31:0,i=0;for(const x of DATA[which]){const p=predictedParty(x);if(p==='D')d++;else if(p==='R')r++;else i++;}return {D:d,R:r,I:i};}
